1	// The replies an assistant offers to tap. Its instructions tell it to end a
2	// message with one line, "Choices: first | second | third"; the page draws
3	// that line as chips instead of text. A message without it is just text, and
4	// the person types their answer.
5	//
6	// The model does not always break the line: "Set it to 0.6? Choices: Yes |
7	// Not yet" is the same offer, so the choices are read from the last line
8	// wherever "Choices:" starts a word in it.
9	
10	const CHOICES = /(^|\s)Choices:(.*)$/;
11	// While streaming: the end of the text that is, or may yet become, "Choices:".
12	const PARTIAL = /(^|\s)(C(h(o(i(c(e(s(:.*)?)?)?)?)?)?)?)$/;
13	
14	function lastLine(text: string): { before: string; line: string } {
15	  const trimmed = text.trimEnd();
16	  const cut = trimmed.lastIndexOf('\n');
17	  return { before: trimmed.slice(0, cut + 1), line: trimmed.slice(cut + 1) };
18	}
19	
20	// A finished message: its text without the choices, and the choices.
21	export function splitChoices(text: string): { body: string; choices: string[] } {
22	  const { before, line } = lastLine(text);
23	  const found = CHOICES.exec(line);
24	  if (!found) return { body: text, choices: [] };
25	  const choices = found[2]
26	    .split('|')
27	    .map((choice) => choice.trim())
28	    .filter(Boolean);
29	  return { body: (before + line.slice(0, found.index)).trimEnd(), choices };
30	}
31	
32	// A message still streaming: the same text, minus an end that is, or may yet
33	// become, the choices, so it never shows as text first.
34	export function withoutPartialChoices(text: string): string {
35	  const { before, line } = lastLine(text);
36	  const found = CHOICES.exec(line) ?? PARTIAL.exec(line);
37	  return found ? (before + line.slice(0, found.index)).trimEnd() : text;
38	}
