// Builds project/agent-ui-reply-choices-proposal.dc.html for the JusPrin v2 canvas.
import { writeFileSync, mkdirSync } from 'node:fs';
import path from 'node:path';

const root = process.argv[2];
const W = 922, H = 1300;
const box = 'box-sizing:border-box;flex:none;';
const QUESTION = 'This looks like a T-shaped bracket with a hole for a screw. What will it do once it’s printed?';
const LABELS = ['Hold a shelf', 'Decoration', 'Just a test'];

const text = (cls, color, s, extra = '') =>
  `<div class="${cls}" style="${box}${extra}color:${color}">${s}</div>`;

// The chip as it ships today: Chat/Reply Choice.
const todayChip = (label, state = 'Normal') => {
  const fill = { Normal: 'var(--surface-canvas)', Hover: 'var(--action-primary-hover)' }[state];
  const ink = state === 'Normal' ? 'var(--action-primary)' : 'var(--action-on-primary)';
  return `<div data-c="Chat/Reply Choice:State=${state}" style="${box}height:var(--component-replyChip-height);display:flex;padding:0px var(--component-replyChip-paddingX);justify-content:center;align-items:center;background:${fill};border-radius:var(--radius-small);box-shadow:inset 0 0 0 1px var(--border-strong)">${text('body-small', ink, label, 'white-space:nowrap;')}</div>`;
};

// The proposal: the person's bubble tint, a full capsule, no strong outline.
// 999px stands for the extended radius-full (a capsule at any height).
const chip = (label, state = 'Normal', stroke = false) => {
  const fill = { Normal: 'var(--surface-subtle)', Hover: 'var(--surface-selected)', Pressed: 'var(--surface-selected)',
                 Focus: 'var(--surface-subtle)', Disabled: 'var(--action-disabled)' }[state];
  const ink = state === 'Disabled' ? 'var(--action-disabled-text)' : 'var(--text-primary)';
  const ring = state === 'Focus' ? 'outline:2px solid var(--border-focus);outline-offset:2px;' : '';
  const edge = stroke ? 'box-shadow:inset 0 0 0 1px var(--border-subtle);' : '';
  return `<div data-c="Chat/Reply Choice (proposed):State=${state}" style="${box}height:var(--component-replyChip-height);display:flex;padding:0px var(--component-replyChip-paddingX);justify-content:center;align-items:center;background:${fill};border-radius:999px;${edge}${ring}">${text('body-small', ink, label, 'white-space:nowrap;')}</div>`;
};

const agent = (s) =>
  `<div data-c="Chat Bubble:Role=Agent" style="${box}align-self:stretch;display:flex;padding:var(--space-4) 0px">${text('body-small', 'var(--text-primary)', s, 'flex:1 1 0;min-width:0;')}</div>`;
const user = (s) =>
  `<div data-c="Chat Bubble:Role=User" style="${box}align-self:flex-end;max-width:75%;display:flex;padding:var(--space-8) var(--space-12);background:var(--surface-subtle);border-radius:var(--radius-medium)">${text('body-small', 'var(--text-primary)', s)}</div>`;
const chips = (items) =>
  `<div data-n="Reply choices" style="${box}align-self:stretch;display:flex;flex-wrap:wrap;gap:var(--space-8);margin-top:var(--space-4)">${items.join('')}</div>`;

// A card: a numbered title, a one-line note, then a chat column on its own canvas.
const card = (title, note, body, { wide = false, theme = 'light' } = {}) =>
