// Restyles every Chat/Reply Choice drawn on the canvas boards given, to the
// decided look: surface-subtle with a border-subtle stroke, text-primary,
// radius-full; hover and pressed surface-selected.
import { readFileSync, writeFileSync } from 'node:fs';

const look = {
  'Normal': ['var(--surface-subtle)', 'inset 0 0 0 1px var(--border-subtle)', 'var(--text-primary)'],
  'Hover': ['var(--surface-selected)', 'inset 0 0 0 1px var(--border-subtle)', 'var(--text-primary)'],
  'Pressed': ['var(--surface-selected)', 'inset 0 0 0 1px var(--border-subtle)', 'var(--text-primary)'],
  'Keyboard focus': ['var(--surface-subtle)', 'inset 0 0 0 2px var(--border-focus)', 'var(--text-primary)'],
  'Disabled': ['var(--action-disabled)', 'inset 0 0 0 1px var(--border-subtle)', 'var(--action-disabled-text)'],
};
const chip = /<div (data-n="State=|data-c="Chat\/Reply Choice:State=)([^"]+)" style="([^"]*)"><div class="body-small" style="([^"]*)">/g;

for (const file of process.argv.slice(2)) {
  let n = 0;
  let html = readFileSync(file, 'utf8').replace(chip, (m, attr, state, outer, inner) => {
    // Only reply choices: a 28px box in the reply-choice padding.
    if (!look[state] || !outer.includes('height:28px')) return m;
    const [bg, edge, ink] = look[state];
    n++;
    outer = outer.replace(/width:(72|121)px;/, '').replace(/background:[^;]+;/, `background:${bg};`)
      .replace('border-radius:var(--radius-small)', 'border-radius:var(--radius-full)')
      .replace(/box-shadow:[^;]+;/, `box-shadow:${edge};`);
    inner = inner.replace(/color:[^;"]+/, `color:${ink}`);
    return `<div ${attr}${state}" style="${outer}"><div class="body-small" style="${inner}">`;
  });
  html = html.replace('Suggested answer · 28 DIP height · space/12 horizontal padding',
    'Suggested answer · a reply the person could send · 28 DIP capsule (radius-full) · space/12 horizontal padding');
  writeFileSync(file, html);
  console.log(file.split(/[\\/]/).pop(), n);
}

